using System;

namespace EInvoiceValidationNet.Core.Configuration
{
    /// <summary>
    /// Configures how the validation report of a scenario is generated by transforming the report input document
    /// with an XSLT stylesheet (the <c>createReport</c> element of <c>scenarios.xml</c>).
    /// </summary>
    public sealed class ReportTransformationConfiguration
    {
        /// <summary>
        /// Initializes a report transformation.
        /// </summary>
        /// <param name="xsltFilePath">Required. Path of the XSLT 2.0 stylesheet that creates the report from the report input document. It is trimmed.</param>
        /// <param name="name">Optional. Human readable name of the report transformation, e.g. shown as the name of the validation step. It is trimmed.</param>
        /// <param name="outputDirectory">Optional. Directory the generated report is written to; <c>null</c> means the report is not saved as a file,
        /// but you can access it in memory via the ValidationResult. It is trimmed.</param>
        /// <exception cref="ArgumentNullException">Thrown when <paramref name="xsltFilePath"/> is <c>null</c>.</exception>
        public ReportTransformationConfiguration(string xsltFilePath, string name, string outputDirectory)
        {
            if (xsltFilePath is null)
            {
                throw new ArgumentNullException(nameof(xsltFilePath));
            }

            XsltFilePath = xsltFilePath.Trim();
            Name = name?.Trim();
            OutputDirectory = outputDirectory?.Trim();
            OriginalLocation = XsltFilePath;
        }

        /// <summary>
        /// Path of the report XSLT. Relative references inside the stylesheet resolve next to this file.
        /// </summary>
        public string XsltFilePath { get; }

        /// <summary>
        /// The optional name of the report transformation, or <c>null</c> when the configuration did not specify one.
        /// </summary>
        public string Name { get; }

        /// <summary>
        /// The optional directory for the generated report, or <c>null</c> when no file writing should be done.
        /// </summary>
        public string OutputDirectory { get; }

        /// <summary>
        /// The resource location as it was configured (the absolute <see cref="XsltFilePath"/> for code-defined
        /// configurations, the original relative location for <c>scenarios.xml</c> configurations). It is embedded in the
        /// report input.
        /// </summary>
        internal string OriginalLocation { get; set; }
    }
}
